"use client";

import { useCallback, useRef, useState, type ReactNode } from "react";
import { AnimatePresence } from "motion/react";

import { cn } from "../lib/cn";
import { HEADING_TAGS, headingBelow } from "../lib/heading";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { duration, ease, spring } from "../motion/tokens";
import { SheenLogo } from "../logo/logo";

import {
  type AuthSplitValues,
  defaultAuthSplitLabels,
  defaultAuthSplitTestimonials,
  type AuthSplitProps,
} from "./auth-split/model";
import { MotionGlassCard, settleNestedGlass } from "./auth-split/utils";
import { SignUpForm } from "./auth-split/form";
import { SuccessView, BrandPanel } from "./auth-split/brand";

export {
  type AuthSplitValues,
  type AuthSplitTestimonial,
  type AuthSplitStat,
  type AuthSplitLabels,
  defaultAuthSplitLabels,
  defaultAuthSplitTestimonials,
  type AuthSplitProps,
} from "./auth-split/model";
export { passwordStrength } from "./auth-split/utils";

/**
 * Auth split: a split-screen sign-up page.
 *
 *   <AuthSplit onSubmit={(values) => api.signUp(values)} onSocial={(p) => signInWith(p)} />
 *
 * Left, a dark brand panel: a slow aurora of colour, a light that follows the pointer, the
 * headline, a feature list, a few numbers and rotating testimonials (with pause and dots).
 * Right, a glass sign-up card in the GlassLogin style: social buttons, name, email, a
 * password with a live strength meter and checklist, the terms checkbox, then a "check your
 * inbox" state once the account is created.
 *
 * The brand panel is a "dark island": it sets color-scheme: dark, so every SheenUI token
 * inside it (text, glass, accents) resolves to its dark value in either theme, and its text
 * keeps AA contrast on the dark ground.
 *
 * Responsive by its own width (container queries): from 56rem the two halves sit side by
 * side; narrower, the form comes first under a small logo and the brand panel follows it.
 *
 * Motion: the aurora drifts (transform only) and the card swaps by animating the glass card
 * itself; while it fades, the glass nested in it (inputs, social buttons) drops its blur, so no
 * backdrop-filter ever sits inside a fading element. Strength segments fill by scaleX.
 * Reduced motion: no drift, no auto-rotation of testimonials (use the dots), the card swaps at once.
 */

/** The glass card that swaps between the form and "check your inbox": it rises in, and leaves quicker without overshoot. */
function SwapCard({ reduced, className, children }: { reduced: boolean; className?: string; children: ReactNode }) {
  const ref = useRef<HTMLDivElement | null>(null);
  // A card that mounts faded out (to animate in) has its whole subtree in place here: its nested
  // glass starts unblurred, before the first frame. One that mounts as is (first render) is left alone.
  const attach = useCallback((node: HTMLDivElement | null) => {
    ref.current = node;
    if (node && Number.parseFloat(getComputedStyle(node).opacity) < 0.999) settleNestedGlass(node, true);
  }, []);
  return (
    <MotionGlassCard
      ref={attach}
      level={3}
      initial={reduced ? { opacity: 0 } : { opacity: 0, y: 16, scale: 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1, transition: reduced ? { duration: duration.fast } : spring.gentle }}
      exit={{
        opacity: 0,
        y: reduced ? 0 : -8,
        scale: reduced ? 1 : 0.99,
        transition: { duration: duration.exit, ease: ease.exit },
      }}
      onAnimationStart={() => settleNestedGlass(ref.current, true)}
      onAnimationComplete={() => {
        // Blur comes back only once the card is fully opaque (not at the end of its exit).
        const node = ref.current;
        if (node && Number.parseFloat(getComputedStyle(node).opacity) >= 0.999) settleNestedGlass(node, false);
      }}
      className={className}
    >
      {children}
    </MotionGlassCard>
  );
}

/**
 * Props (see `AuthSplitProps`): `title`, `subtitle`, `headline`, `description`, `features`, `stats`,
 * `testimonials` (`defaultAuthSplitTestimonials`), `rotateEvery` (`7` s), `brand`, `onSubmit(values)`,
 * `onSocial(provider)`, `onResend(email)`, `termsHref`, `privacyHref`, `signInHref` (`"#"`, `null` hides
 * it), `minPasswordLength` (`8`), `reverse` (`false`), `headingLevel` (`1`), `labels`, `className`.
 * Keyboard: Tab walks name, email, password (with its reveal button and strength checklist), the terms
 * checkbox, submit and the social buttons; Enter submits; a failed check moves focus to the first
 * invalid field. Testimonials rotate with a pause button and dots, both reachable by keyboard.
 * Accessibility: a real `<form>` with linked error text (`role="alert"` for a failed submit), a
 * `role="meter"` password-strength bar with the checklist as text, and polite status regions; the
 * success screen takes focus.
 * Glass and motion: the form is one glass card beside a dark brand panel whose aurora drifts (transform
 * only); the card swaps by animating the glass card itself. Reduced motion: no drift, no auto-rotation
 * (use the dots) and the card swaps at once.
 *
 * @example
 * ```tsx
 * import { AuthSplit } from "@sheenui/theme";
 *
 * const post = (url: string, body: unknown) => fetch(url, { method: "POST", body: JSON.stringify(body) });
 * const startOAuth = (provider: string) => {
 *   window.location.href = `/auth/${provider}`;
 * };
 *
 * export function Example() {
 *   return (
 *     <AuthSplit
 *       headline="Build faster with glass"
 *       onSubmit={async ({ name, email, password }) => {
 *         await post("/api/sign-up", { name, email, password }); // throw to show an error above the button
 *       }}
 *       onSocial={(provider) => startOAuth(provider)}
 *       onResend={async (email) => {
 *         await post("/api/resend", { email });
 *       }}
 *     />
 *   );
 * }
 * ```
 *
 * @see /blocks/signup-page
 */
export function AuthSplit({
  title,
  subtitle,
  headline,
  description,
  features = [
    "Forty-plus glass components, copy-paste ready",
    "Motion that bows out for reduced-motion users",
    "AA contrast in light and dark, measured",
  ],
  stats = [
    { value: "12,400+", label: "teams building" },
    { value: "4.9/5", label: "average rating" },
    { value: "99.99%", label: "uptime last year" },
  ],
  testimonials = defaultAuthSplitTestimonials,
  rotateEvery = 7,
  brand,
  onSubmit,
  onSocial,
  onResend,
  termsHref = "#",
  privacyHref = "#",
  signInHref = "#",
  minPasswordLength = 8,
  reverse = false,
  headingLevel = 1,
  labels,
  className,
}: AuthSplitProps) {
  const L = { ...defaultAuthSplitLabels, ...labels };
  const reduced = useSheenReducedMotion();
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const logo = brand ?? <SheenLogo px={30} />;

  const [done, setDone] = useState<string | null>(null);
  // Back from the success screen: the form opens with the email field focused.
  const [returning, setReturning] = useState(false);
  const emailRef = useRef<HTMLInputElement>(null);
  const [values, setValues] = useState<AuthSplitValues & { terms: boolean }>({
    name: "",
    email: "",
    password: "",
    terms: false,
  });

  const card = "w-full max-w-md rounded-sheen-xl p-6 @lg/auth:p-8";

  return (
    <div data-slot="auth-split" className={cn("@container/auth w-full min-w-0", className)}>
      <div
        className={cn(
          "grid min-h-[inherit] grid-cols-[minmax(0,1fr)] gap-3 p-2 @lg/auth:p-3",
          "@4xl/auth:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)]",
          reverse && "@4xl/auth:grid-cols-[minmax(0,1fr)_minmax(0,1.05fr)]",
        )}
      >
        {/* The form comes first in the DOM (reading and tab order); wide layouts move the panel to its left. */}
        <div
          className={cn(
            "flex min-w-0 flex-col items-center justify-center gap-6 px-2 py-6 @lg/auth:px-6 @4xl/auth:py-10",
            !reverse && "@4xl/auth:order-2",
          )}
        >
          {/* Narrow: the brand panel sits below the form, so the logo leads here. */}
          <div className="flex w-full max-w-md @4xl/auth:hidden">{logo}</div>

          <AnimatePresence mode="wait" initial={false}>
            {done === null ? (
              <SwapCard key="form" reduced={reduced} className={card}>
                <SignUpForm
                  Heading={Heading}
                  title={title ?? L.title}
                  subtitle={subtitle ?? L.subtitle}
                  values={values}
                  setValues={setValues}
                  emailRef={emailRef}
                  L={L}
                  onSubmit={onSubmit}
                  onSocial={onSocial}
                  termsHref={termsHref}
                  privacyHref={privacyHref}
                  signInHref={signInHref}
                  minPasswordLength={minPasswordLength}
                  focusEmailOnMount={returning}
                  onDone={setDone}
                />
              </SwapCard>
            ) : (
              <SwapCard key="done" reduced={reduced} className={card}>
                <SuccessView
                  Heading={Heading}
                  email={done}
                  L={L}
                  onResend={onResend}
                  onBack={() => {
                    setReturning(true);
                    setDone(null);
                  }}
                />
              </SwapCard>
            )}
          </AnimatePresence>
        </div>

        <BrandPanel
          logo={logo}
          headline={headline}
          description={description}
          features={features}
          stats={stats}
          testimonials={testimonials}
          rotateEvery={rotateEvery}
          headingLevel={headingLevel}
          L={L}
          className={reverse ? undefined : "@4xl/auth:order-1"}
        />
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type PointerEvent, type ReactNode } from "react";
import { motion } from "motion/react";

import { cn } from "../../lib/cn";
import { HEADING_TAGS, headingBelow, type HeadingTag, type HeadingLevelOption } from "../../lib/heading";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { useLoopPlayback } from "../../motion/gate";
import { duration, ease, spring } from "../../motion/tokens";
import { Button } from "../../button/button";
import { CheckIcon } from "../icons";
import { type AuthSplitTestimonial, type AuthSplitStat, type AuthSplitLabels, type AuthSplitProps } from "./model";
import { StarIcon, QuoteIcon, PauseIcon, PlayIcon, SendIcon } from "./utils";

/* ---------- Success ---------- */

/** The panel that replaces the form once sign-up succeeds. @internal */
export function SuccessView({
  Heading,
  email,
  L,
  onResend,
  onBack,
}: {
  Heading: HeadingTag;
  email: string;
  L: AuthSplitLabels;
  onResend?: AuthSplitProps["onResend"];
  onBack: () => void;
}) {
  const reduced = useSheenReducedMotion();
  const [state, setState] = useState<"idle" | "sending" | "sent">("idle");
  const headingRef = useRef<HTMLHeadingElement>(null);

  // The submit button that had focus is gone: land on the new heading, so the result is read out.
  useEffect(() => {
    headingRef.current?.focus({ preventScroll: true });
  }, []);

  async function resend() {
    if (state !== "idle") return;
    setState("sending");
    try {
      await onResend?.(email);
      setState("sent");
    } catch {
      setState("idle");
    }
  }

  return (
    <div className="flex flex-col items-center gap-5 py-4 text-center">
      <span className="relative flex size-16 items-center justify-center">
        {!reduced && (
          <motion.span
            aria-hidden
            className="absolute inset-0 rounded-full border-2 border-sheen-success"
            initial={{ scale: 0.8, opacity: 0.7 }}
            animate={{ scale: 1.8, opacity: 0 }}
            transition={{ duration: duration.slower * 1.5, ease: ease.out, delay: 0.15 }}
          />
        )}
        <motion.span
          aria-hidden
          initial={reduced ? false : { scale: 0.4, rotate: -16 }}
          animate={{ scale: 1, rotate: 0 }}
          transition={{ ...spring.bouncy, delay: 0.05 }}
          className="flex size-16 items-center justify-center rounded-full bg-sheen-success-soft text-sheen-success-text forced-colors:border forced-colors:border-[CanvasText]"
        >
          <SendIcon className="size-7" />
        </motion.span>
      </span>
      <div className="flex flex-col gap-2">
        <Heading ref={headingRef} tabIndex={-1} className="text-2xl font-semibold tracking-tight outline-none">
          {L.successTitle}
        </Heading>
        <p className="text-sm text-pretty text-sheen-fg-muted">{L.successBody(email)}</p>
      </div>
      <div className="flex w-full flex-col gap-2">
        {onResend && (
          <Button
            variant="glass"
            fullWidth
            loading={state === "sending"}
            onClick={resend}
            // aria-disabled, not disabled: the button keeps focus after it has done its job.
            aria-disabled={state === "sent" || undefined}
            data-unavailable={state === "sent" ? "" : undefined}
            className="data-unavailable:pointer-events-none data-unavailable:opacity-55"
          >
            {state === "sent" ? (
              <>
                <CheckIcon />
                {L.resent}
              </>
            ) : (
              L.resend
            )}
          </Button>
        )}
        <Button variant="ghost" fullWidth onClick={onBack}>
          {L.changeEmail}
        </Button>
      </div>
      <span role="status" className="sr-only">
        {state === "sent" ? L.resent : ""}
      </span>
    </div>
  );
}

/* ---------- Brand panel ---------- */

/** The brand side of the split layout: logo, headline and testimonials. @internal */
export function BrandPanel({
  logo,
  headline,
  description,
  features,
  stats,
  testimonials,
  rotateEvery,
  headingLevel,
  L,
  className,
}: {
  logo: ReactNode;
  headline?: ReactNode;
  description?: ReactNode;
  features: ReactNode[];
  stats: AuthSplitStat[];
  testimonials: AuthSplitTestimonial[];
  rotateEvery: number;
  headingLevel: HeadingLevelOption;
  L: AuthSplitLabels;
  className?: string;
}) {
  const panelRef = useRef<HTMLDivElement>(null);

  // A soft light follows the pointer (mouse and pen; a finger is scrolling).
  function onPointerMove(event: PointerEvent<HTMLDivElement>) {
    if (event.pointerType === "touch") return;
    const el = panelRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    el.style.setProperty("--mx", `${event.clientX - rect.left}px`);
    el.style.setProperty("--my", `${event.clientY - rect.top}px`);
  }

  return (
    <div
      ref={panelRef}
      onPointerMove={onPointerMove}
      data-slot="auth-split-panel"
      // Dark island: tokens inside resolve to their dark values in either theme.
      className={cn(
        "group/panel relative isolate flex min-w-0 flex-col justify-between gap-10 overflow-hidden rounded-sheen-xl bg-sheen-bg p-6 text-sheen-fg [color-scheme:dark] @lg/auth:p-10",
        "shadow-[0_0_0_1px_var(--sheen-glass-edge),0_24px_64px_-24px_var(--sheen-shadow-far)]",
        "forced-colors:border forced-colors:border-[CanvasText]",
        className,
      )}
    >
      <Aurora />

      <div className="hidden @4xl/auth:flex">{logo}</div>

      <div className="flex flex-col gap-6">
        <p className="max-w-lg text-3xl leading-[1.1] font-semibold tracking-tight text-balance @lg/auth:text-4xl">
          {headline ?? (
            <>
              Interfaces that{" "}
              <span className="bg-clip-text text-transparent [background-image:linear-gradient(120deg,var(--sheen-violet-300),var(--sheen-teal-300))] forced-colors:text-[CanvasText] forced-colors:[background-image:none]">
                feel expensive
              </span>
              , shipped this afternoon.
            </>
          )}
        </p>
        <p className="max-w-md text-base text-pretty text-sheen-fg-muted">
          {description ?? "Glass components with motion that respects your users, ready to drop into any React app."}
        </p>

        {features.length > 0 && (
          <ul className="flex flex-col gap-2.5">
            {features.map((feature, i) => (
              <li key={i} className="flex items-start gap-3 text-sm">
                <span
                  aria-hidden
                  className="mt-px flex size-5 shrink-0 items-center justify-center rounded-full bg-sheen-accent-soft text-sheen-accent ring-1 ring-sheen-accent-border"
                >
                  <CheckIcon className="size-3" strokeWidth="2.6" />
                </span>
                <span className="text-sheen-fg">{feature}</span>
              </li>
            ))}
          </ul>
        )}

        {stats.length > 0 && (
          <dl className="grid grid-cols-[repeat(auto-fit,minmax(min(100%,5.5rem),1fr))] gap-3 border-t border-sheen-border pt-6">
            {stats.map((stat, i) => (
              <div key={i} className="flex min-w-0 flex-col-reverse gap-0.5">
                <dt className="text-xs text-sheen-fg-muted">{stat.label}</dt>
                <dd className="text-xl font-semibold tracking-tight tabular-nums break-words @lg/auth:text-2xl">
                  {stat.value}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      {testimonials.length > 0 && (
        <Testimonials items={testimonials} rotateEvery={rotateEvery} headingLevel={headingLevel} L={L} />
      )}
    </div>
  );
}

/** Decorative colour: three drifting blobs, a fine grid and the pointer light. Transform-only motion. */
export function Aurora() {
  // The wrapper is as tall as the whole panel, so the shared off-screen pause (which watches the parent) would see it
  // as on screen whenever any of the panel is; the blobs themselves ask for the pause (also in a hidden tab).
  const ref = useRef<HTMLDivElement>(null);
  const playing = useLoopPlayback(ref, { margin: "0px", respectReducedMotion: false });
  const blob =
    "pointer-events-none absolute rounded-full motion-ok:animate-[sheen-float_var(--sheen-duration-ambient)_var(--sheen-ease-in-out)_infinite] in-data-[paused]:[animation-play-state:paused]";
  return (
    <div
      ref={ref}
      aria-hidden
      data-paused={playing ? undefined : ""}
      className="pointer-events-none absolute inset-0 -z-10 forced-colors:hidden"
    >
      <span
        className={cn(
          blob,
          "-top-1/4 -start-1/4 size-[70%] [background:radial-gradient(closest-side,color-mix(in_oklch,var(--sheen-violet-500)_70%,transparent),transparent)]",
        )}
      />
      <span
        className={cn(
          blob,
          "top-1/3 -end-1/3 size-[75%] [background:radial-gradient(closest-side,color-mix(in_oklch,var(--sheen-teal-500)_45%,transparent),transparent)] [animation-delay:var(--sheen-loop-phase-a)]",
        )}
      />
      <span
        className={cn(
          blob,
          "-bottom-1/3 start-[10%] size-[65%] [background:radial-gradient(closest-side,var(--sheen-blob-3),transparent)] [animation-delay:var(--sheen-loop-phase-b)]",
        )}
      />
      {/* Fine grid, fading out toward the edges. */}
      <span className="absolute inset-0 [background-image:linear-gradient(to_bottom,var(--sheen-backdrop-grid)_1px,transparent_1px),linear-gradient(to_right,var(--sheen-backdrop-grid)_1px,transparent_1px)] [background-size:36px_36px] [mask-image:radial-gradient(ellipse_at_30%_20%,#000,transparent_70%)]" />
      {/* Pointer light. */}
      <span className="absolute inset-0 opacity-0 transition-opacity duration-(--sheen-duration-slow) group-hover/panel:opacity-100 [background:radial-gradient(420px_circle_at_var(--mx,50%)_var(--my,30%),color-mix(in_oklch,var(--sheen-violet-300)_16%,transparent),transparent_65%)]" />
    </div>
  );
}

/** The auto-advancing testimonial carousel of the brand panel. @internal */
export function Testimonials({
  items,
  rotateEvery,
  headingLevel,
  L,
}: {
  items: AuthSplitTestimonial[];
  rotateEvery: number;
  headingLevel: HeadingLevelOption;
  L: AuthSplitLabels;
}) {
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 1)];
  const reduced = useSheenReducedMotion();
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [held, setHeld] = useState(false);
  const [manual, setManual] = useState(false);
  const many = items.length > 1;
  // Reduced motion: no auto-rotation at all; the dots still switch quotes.
  const auto = many && rotateEvery > 0 && !reduced;
  const sectionRef = useRef<HTMLElement>(null);
  // The rotation also waits while the card is off-screen or the tab is hidden.
  const visible = useLoopPlayback(sectionRef, { respectReducedMotion: false });
  const running = auto && !paused && !held && visible;
  const headingId = useId();

  useEffect(() => {
    if (!running) return;
    const timer = window.setTimeout(() => setIndex((i) => (i + 1) % items.length), rotateEvery * 1000);
    return () => window.clearTimeout(timer);
  }, [running, index, items.length, rotateEvery]);

  return (
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- hover and focus only pause the quote rotation (WCAG 2.2.2); they activate nothing
    <section
      ref={sectionRef}
      role="group"
      aria-labelledby={headingId}
      onPointerEnter={() => setHeld(true)}
      onPointerLeave={() => setHeld(false)}
      onFocus={() => setHeld(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setHeld(false);
      }}
      className="glass-2 relative flex flex-col gap-4 rounded-sheen-xl p-5 @lg/auth:p-6"
    >
      <Heading id={headingId} className="sr-only">
        {L.testimonials}
      </Heading>
      <QuoteIcon aria-hidden className="absolute top-4 end-5 size-9 text-sheen-accent opacity-30" />

      {/* All quotes share one grid cell, so the card is as tall as the longest and never jumps. */}
      <div className="grid" aria-live={manual || !running ? "polite" : "off"}>
        {items.map((item, i) => {
          const active = i === index;
          return (
            <figure
              key={i}
              aria-hidden={!active}
              inert={!active}
              className={cn(
                "col-start-1 row-start-1 flex flex-col gap-4",
                // Hand-over, not a cross-fade: the old quote leaves quickly, the new one rises in after it.
                active
                  ? "opacity-100 transition-[opacity,translate] delay-(--sheen-duration-exit) duration-(--sheen-duration-slow) ease-sheen-out"
                  : "pointer-events-none opacity-0 transition-[opacity,translate] duration-(--sheen-duration-exit) ease-sheen-exit motion-ok:-translate-y-1.5",
              )}
            >
              {item.rating !== undefined && (
                <div className="flex gap-0.5 text-sheen-warning" role="img" aria-label={L.rating(item.rating)}>
                  {[0, 1, 2, 3, 4].map((star) => (
                    <StarIcon
                      key={star}
                      className={cn("size-4", star >= Math.round(item.rating ?? 0) && "opacity-25")}
                    />
                  ))}
                </div>
              )}
              <blockquote className="pe-8 text-base leading-relaxed text-pretty text-sheen-fg">
                {/* Quote marks come from CSS for the page's language (“…” in English, „…“ in German, «…» in French). */}
                <p className="[quotes:auto] before:content-[open-quote] after:content-[close-quote]">{item.quote}</p>
              </blockquote>
              <figcaption className="flex items-center gap-3">
                <span
                  aria-hidden
                  className="sheen-fill flex size-10 shrink-0 items-center justify-center rounded-full text-sm font-semibold text-sheen-accent-fg [background-image:var(--sheen-accent-fill)]"
                >
                  {item.name
                    .split(/\s+/)
                    .slice(0, 2)
                    .map((p) => p[0])
                    .join("")}
                </span>
                <span className="flex min-w-0 flex-col">
                  <span className="text-sm font-semibold">{item.name}</span>
                  {item.role && <span className="text-xs text-sheen-fg-muted">{item.role}</span>}
                </span>
              </figcaption>
            </figure>
          );
        })}
      </div>

      {many && (
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-1">
            {items.map((_, i) => {
              const active = i === index;
              return (
                <button
                  key={i}
                  type="button"
                  aria-label={L.showTestimonial(i + 1, items.length)}
                  aria-current={active ? "true" : undefined}
                  onClick={() => {
                    setManual(true);
                    setIndex(i);
                  }}
                  className={cn(
                    "group/dot relative flex h-6 min-w-6 items-center justify-center rounded-sheen-full px-1",
                    "focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-sheen-focus",
                    "any-pointer-coarse:h-11 any-pointer-coarse:min-w-11 any-pointer-coarse:px-2",
                  )}
                >
                  <span
                    className={cn(
                      "relative block h-1.5 overflow-hidden rounded-full bg-sheen-border",
                      active ? "w-8" : "w-1.5 group-hover/dot:bg-sheen-fg-subtle",
                      "forced-colors:border forced-colors:border-[CanvasText]",
                    )}
                  >
                    {active && (
                      // Fills over one rotation (scaleX, transform only); full while paused or held.
                      <motion.span
                        key={`${index}-${running}`}
                        initial={running ? { scaleX: 0 } : false}
                        animate={{ scaleX: 1 }}
                        transition={{ duration: running ? rotateEvery : 0, ease: "linear" }}
                        className="absolute inset-0 origin-left rounded-full bg-sheen-fg rtl:origin-right forced-colors:bg-[Highlight]"
                      />
                    )}
                  </span>
                </button>
              );
            })}
          </div>
          {auto && (
            <Button
              variant="ghost"
              size="sm"
              // The label says what pressing does (WAI carousel pattern), so no aria-pressed on top of it.
              aria-label={paused ? L.play : L.pause}
              onClick={() => setPaused((p) => !p)}
              className="size-8 px-0 text-sheen-fg-muted hover:text-sheen-fg"
            >
              {paused ? <PlayIcon /> : <PauseIcon />}
            </Button>
          )}
        </div>
      )}
    </section>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type SubmitEvent, type ReactNode, type RefObject } from "react";

import { cn } from "../../lib/cn";
import type { HeadingTag } from "../../lib/heading";
import { Button } from "../../button/button";
import { Checkbox } from "../../checkbox/checkbox";
import { Input } from "../../input/input";
import { AlertIcon, CheckIcon, EyeIcon, GithubIcon, GoogleIcon, LockIcon, MailIcon } from "../icons";
import { type AuthSplitValues, type AuthSplitLabels, type AuthSplitProps } from "./model";
import { passwordStrength, UserIcon, type Strength, strengthTone, type Errors, link } from "./utils";

/* ---------- Form ---------- */

/** The sign-up form: fields, validation, strength meter and submit. @internal */
export function SignUpForm({
  Heading,
  title,
  subtitle,
  values,
  setValues,
  emailRef,
  L,
  onSubmit,
  onSocial,
  termsHref,
  privacyHref,
  signInHref,
  minPasswordLength,
  focusEmailOnMount,
  onDone,
}: {
  Heading: HeadingTag;
  title: ReactNode;
  subtitle: ReactNode;
  values: AuthSplitValues & { terms: boolean };
  setValues: (fn: (v: AuthSplitValues & { terms: boolean }) => AuthSplitValues & { terms: boolean }) => void;
  emailRef: RefObject<HTMLInputElement | null>;
  L: AuthSplitLabels;
  onSubmit?: AuthSplitProps["onSubmit"];
  onSocial?: AuthSplitProps["onSocial"];
  termsHref: string;
  privacyHref: string;
  signInHref: string | null;
  minPasswordLength: number;
  focusEmailOnMount: boolean;
  onDone: (email: string) => void;
}) {
  const titleId = useId();
  const meterId = useId();
  const rulesId = useId();
  const termsErrorId = useId();
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Errors>({});
  const nameRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const termsRef = useRef<HTMLButtonElement>(null);
  const pendingFocus = useRef<HTMLElement | null>(null);

  const strength = passwordStrength(values.password, minPasswordLength);

  // The card mounts after the success card has left (AnimatePresence "wait"), so focus from here.
  useEffect(() => {
    if (focusEmailOnMount) emailRef.current?.focus();
  }, [focusEmailOnMount, emailRef]);

  // Focus the first invalid field one frame after the errors render (messages are linked by then).
  useEffect(() => {
    const el = pendingFocus.current;
    if (!el) return;
    const frame = requestAnimationFrame(() => {
      pendingFocus.current = null;
      el.focus();
    });
    return () => cancelAnimationFrame(frame);
  }, [errors]);

  const check = {
    name: (v: string) => (v.trim() ? undefined : L.nameRequired),
    email: (v: string) => (/^\S+@\S+\.\S+$/.test(v.trim()) ? undefined : L.invalidEmail),
    password: (v: string) => {
      const s = passwordStrength(v, minPasswordLength);
      return s.rules[0]?.met && s.score >= 2 && !s.common ? undefined : L.weakPassword;
    },
    terms: (v: boolean) => (v ? undefined : L.termsRequired),
  };

  function update<K extends keyof typeof values>(key: K, value: (typeof values)[K]) {
    setValues((v) => ({ ...v, [key]: value }));
    // Clear a message as soon as the value is fixed.
    if (key in errors && errors[key as keyof Errors]) {
      const fn = check[key] as (v: unknown) => string | undefined;
      setErrors((e) => ({ ...e, [key]: fn(value), form: undefined }));
    }
  }

  async function handleSubmit(event: SubmitEvent) {
    event.preventDefault();
    if (loading) return;
    const next: Errors = {
      name: check.name(values.name),
      email: check.email(values.email),
      password: check.password(values.password),
      terms: check.terms(values.terms),
    };
    setErrors(next);
    const first = next.name
      ? nameRef.current
      : next.email
        ? emailRef.current
        : next.password
          ? passwordRef.current
          : next.terms
            ? termsRef.current
            : null;
    if (first) {
      pendingFocus.current = first;
      return;
    }
    setLoading(true);
    try {
      await onSubmit?.({ name: values.name.trim(), email: values.email.trim(), password: values.password });
      onDone(values.email.trim());
    } catch (err) {
      setErrors({ form: err instanceof Error && err.message ? err.message : L.genericError });
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <div className="mb-6 flex flex-col gap-1.5">
        <Heading id={titleId} className="text-2xl font-semibold tracking-tight text-balance">
          {title}
        </Heading>
        <p className="text-sm text-sheen-fg-muted">{subtitle}</p>
      </div>

      {onSocial && (
        <>
          <div className="grid grid-cols-2 gap-3">
            <Button
              variant="glass"
              className="any-pointer-coarse:h-11"
              leading={<GithubIcon />}
              onClick={() => onSocial("github")}
            >
              {L.github}
            </Button>
            <Button
              variant="glass"
              className="any-pointer-coarse:h-11"
              leading={<GoogleIcon />}
              onClick={() => onSocial("google")}
            >
              {L.google}
            </Button>
          </div>
          <div className="my-5 flex items-center gap-3 text-xs text-sheen-fg-muted">
            <span aria-hidden className="h-px flex-1 bg-sheen-border" />
            {L.divider}
            <span aria-hidden className="h-px flex-1 bg-sheen-border" />
          </div>
        </>
      )}

      <form noValidate onSubmit={handleSubmit} className="flex flex-col gap-4">
        <Input
          ref={nameRef}
          label={L.name}
          name="name"
          autoComplete="name"
          aria-required
          placeholder={L.namePlaceholder}
          leading={<UserIcon />}
          value={values.name}
          onChange={(e) => update("name", e.target.value)}
          error={errors.name}
        />
        <Input
          ref={emailRef}
          label={L.email}
          name="email"
          type="email"
          autoComplete="email"
          autoCapitalize="none"
          spellCheck={false}
          aria-required
          placeholder={L.emailPlaceholder}
          leading={<MailIcon />}
          value={values.email}
          onChange={(e) => update("email", e.target.value)}
          onBlur={() => {
            if (values.email) setErrors((x) => ({ ...x, email: check.email(values.email) }));
          }}
          error={errors.email}
        />
        <div className="flex flex-col gap-2.5">
          <Input
            ref={passwordRef}
            label={L.password}
            name="password"
            type={showPassword ? "text" : "password"}
            autoComplete="new-password"
            aria-required
            aria-describedby={`${meterId} ${rulesId}`}
            placeholder={L.passwordPlaceholder}
            leading={<LockIcon />}
            trailing={
              <button
                type="button"
                aria-label={showPassword ? L.hidePassword : L.showPassword}
                aria-pressed={showPassword}
                onClick={() => setShowPassword((s) => !s)}
                className="-me-1.5 flex size-8 items-center justify-center rounded-sheen-sm transition-colors duration-(--sheen-duration-fast) hover:text-sheen-fg focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-sheen-focus any-pointer-coarse:-me-3 any-pointer-coarse:size-11"
              >
                <EyeIcon off={showPassword} />
              </button>
            }
            value={values.password}
            onChange={(e) => update("password", e.target.value)}
            error={errors.password}
          />
          <StrengthMeter id={meterId} rulesId={rulesId} strength={strength} minLength={minPasswordLength} L={L} />
        </div>

        <div className="flex flex-col gap-1.5">
          <Checkbox
            ref={termsRef}
            name="terms"
            checked={values.terms}
            onCheckedChange={(checked) => update("terms", checked)}
            aria-invalid={errors.terms ? true : undefined}
            aria-describedby={errors.terms ? termsErrorId : undefined}
            label={
              <span className="font-normal text-sheen-fg-muted">
                {L.terms({
                  terms: (
                    <a href={termsHref} className={link}>
                      {L.termsLink}
                    </a>
                  ),
                  privacy: (
                    <a href={privacyHref} className={link}>
                      {L.privacyLink}
                    </a>
                  ),
                })}
              </span>
            }
          />
          {errors.terms && (
            <p id={termsErrorId} className="ps-8 text-xs font-medium text-sheen-danger-text">
              {errors.terms}
            </p>
          )}
        </div>

        {errors.form && (
          <p
            role="alert"
            className="flex items-start gap-2 rounded-sheen-sm bg-sheen-danger-soft px-3 py-2 text-sm text-sheen-danger-text"
          >
            <AlertIcon className="mt-0.5 size-4 shrink-0" />
            {errors.form}
          </p>
        )}

        <Button type="submit" size="lg" fullWidth loading={loading} className="mt-1">
          {L.submit}
        </Button>
      </form>

      {signInHref !== null && (
        <p className="mt-6 text-center text-sm text-sheen-fg-muted">
          {L.signInPrompt}{" "}
          <a href={signInHref} className={cn(link, "inline-flex items-center any-pointer-coarse:min-h-11")}>
            {L.signIn}
          </a>
        </p>
      )}
    </>
  );
}

/** The password strength bars with the rule checklist. @internal */
export function StrengthMeter({
  id,
  rulesId,
  strength,
  minLength,
  L,
}: {
  id: string;
  rulesId: string;
  strength: Strength;
  minLength: number;
  L: AuthSplitLabels;
}) {
  const { score, rules, common } = strength;
  const level = L.strengthLevel(score);
  const tone = score > 0 ? strengthTone[score as 1 | 2 | 3 | 4] : null;
  const ruleLabels: Record<string, string> = {
    length: L.ruleLength(minLength),
    case: L.ruleCase,
    number: L.ruleNumber,
    symbol: L.ruleSymbol,
  };

  // Announce the level once typing pauses, not on every keystroke.
  const [spoken, setSpoken] = useState("");
  useEffect(() => {
    if (score === 0) return;
    const timer = window.setTimeout(() => setSpoken(L.announceStrength(level)), 700);
    return () => window.clearTimeout(timer);
  }, [score, level, L]);

  return (
    <div className="flex flex-col gap-2.5">
      <div className="flex items-center gap-3">
        <div
          id={id}
          role="meter"
          aria-label={L.strength}
          aria-valuemin={0}
          aria-valuemax={4}
          aria-valuenow={score}
          aria-valuetext={level || "—"}
          className="grid flex-1 grid-cols-4 gap-1.5"
        >
          {[1, 2, 3, 4].map((segment) => (
            <span
              key={segment}
              className="relative h-1.5 overflow-hidden rounded-full bg-sheen-border forced-colors:border forced-colors:border-[CanvasText]"
            >
              <span
                className={cn(
                  "absolute inset-0 origin-left rounded-full rtl:origin-right",
                  "transition-[scale,background-color] duration-(--sheen-duration-snappy) ease-sheen-snappy",
                  tone?.bar,
                  score >= segment ? "scale-x-100" : "scale-x-0",
                  "forced-colors:bg-[Highlight]",
                )}
                style={{ transitionDelay: `${(segment - 1) * 40}ms` }}
              />
            </span>
          ))}
        </div>
        <span
          aria-hidden
          className={cn(
            "min-w-14 shrink-0 text-end text-xs font-semibold whitespace-nowrap",
            tone?.text ?? "text-sheen-fg-muted",
          )}
        >
          {level || L.strength}
        </span>
      </div>
      <ul id={rulesId} className="grid grid-cols-2 gap-x-3 gap-y-1.5 text-xs">
        {rules.map((rule) => (
          <li
            key={rule.id}
            className={cn(
              "flex items-center gap-1.5 transition-colors duration-(--sheen-duration-base)",
              rule.met ? "text-sheen-success-text" : "text-sheen-fg-muted",
            )}
          >
            <span
              aria-hidden
              className={cn(
                "relative flex size-4 shrink-0 items-center justify-center rounded-full border transition-colors duration-(--sheen-duration-base)",
                rule.met ? "border-transparent bg-sheen-success-soft" : "border-sheen-control-border",
              )}
            >
              <CheckIcon
                className={cn(
                  "size-3 transition-[opacity,scale] duration-(--sheen-duration-snappy) ease-sheen-snappy",
                  rule.met ? "opacity-100" : "opacity-0 motion-ok:scale-50",
                )}
                strokeWidth="2.6"
              />
            </span>
            <span>
              {ruleLabels[rule.id]}
              <span className="sr-only">: {rule.met ? L.ruleMet : L.ruleUnmet}</span>
            </span>
          </li>
        ))}
      </ul>
      {common && <p className="text-xs font-medium text-sheen-warning-text">{L.tooCommon}</p>}
      <span role="status" className="sr-only">
        {spoken}
      </span>
    </div>
  );
}

